<script setup>
import { ref,onUnmounted } from 'vue'
import { request } from '../services/request.js'
import { scopedStorage,storageContext } from '../services/storage.js'
import { newHealthRequestId } from '../services/health-task-flow.js'
const props=defineProps({result:Object,memberId:String})
const busy=ref(false),error=ref(''),saved=ref(null)
const names={breakfast:'早餐',lunch:'午餐',dinner:'晚餐',snack:'加餐'}
let alive=true;const scope=storageContext();onUnmounted(()=>alive=false)
async function save(){if(busy.value||!props.result.data?.preview_id||scope!==storageContext())return;busy.value=true;error.value='';const key='chat-plan-save:'+props.result.data.preview_id;try{let pending=scopedStorage.getStorageSync(key);if(!pending){const id=newHealthRequestId();pending={path:'/api/health/v1/members/'+props.memberId+'/meal-plans',method:'POST',headers:{'Idempotency-Key':id},data:{client_request_id:id,preview_id:props.result.data.preview_id}};scopedStorage.setStorageSync(key,pending)}const {data}=await request(pending);if(!alive||scope!==storageContext())return;if(data.member_id!==props.memberId||!data.plan_id)throw new Error('餐单保存回执待核对，请用原请求重试');saved.value=data;scopedStorage.setStorageSync(key,null)}catch(e){if(alive&&scope===storageContext()){error.value=e.message;if([400,403,404,409,422].includes(Number(e.code)))scopedStorage.setStorageSync(key,null)}}finally{if(alive)busy.value=false}}
function inspect(){const id=saved.value?.plan_id||props.result.data?.plan_id;uni.navigateTo({url:'/pages/health/plans?memberId='+encodeURIComponent(props.memberId)+(id?'&planId='+encodeURIComponent(id):'')})}
</script>
<template><view class="business-card"><template v-if="result.kind==='meal_plan_preview'"><text class="section-title">{{result.data.plan_date||'本次'}}餐单预览</text><view v-for="meal in result.data.meals||[]" :key="meal.meal_type"><text>{{names[meal.meal_type]}}</text><text v-for="(dish,i) in meal.dishes||[]" :key="i">{{dish.name}} · {{dish.planned_grams??'份量未知'}}{{dish.planned_grams?' g':''}}</text></view><text class="safe-note">{{saved?'已保存餐单草稿':'预览尚未保存'}}，未自动替换今日安排或记为已吃。</text><button v-if="result.data.preview_id&&!saved" class="secondary-button" :disabled="busy" @click="save">{{busy?'正在核对保存…':'保存这份餐单'}}</button><button v-if="saved||result.data.plan_id" class="secondary-button" @click="inspect">查看已保存餐单 ›</button></template><template v-else-if="result.kind==='diet_analysis'"><text class="section-title">已记录饮食的回顾</text><text v-for="finding in result.data.findings||[]" :key="finding">{{finding}}</text><text class="safe-note">仅依据已确认记录，未记录与缺失数值保持未知。</text></template><template v-else><text class="section-title">{{result.kind==='quality_check'?'餐单核对结果':'食材需求结果'}}</text><text>请结合当前保存的餐单核对本次结果。</text><button class="secondary-button" @click="inspect">查看相关餐单 ›</button></template><text v-if="error" class="inline-error">{{error}}</text></view></template>
<style scoped>.business-card,.business-card>view{display:flex;flex-direction:column;gap:14rpx}.business-card{padding-top:16rpx;font-size:26rpx}.business-card>view{padding:18rpx;background:#fff;border-radius:16rpx}.business-card .safe-note{font-size:25rpx;text-align:left}</style>
